UPDATE companies SET description='Maine Woodworks operates from Saco, Maine, where it was founded in 1991. The company builds custom-made furniture, emphasizing thoughtful design and craftsmanship tailored to individual homes.

The workshop produces made-to-order pieces across bedroom, dining, entryway, farmhouse, occasional, and office categories. Each item is handcrafted from regionally sourced sustainable hardwood using traditional English dovetail joinery, with customizable panel styles, leg and knob options, and eco-friendly finishes. Production lead times run six to eight weeks, and a white-glove delivery service includes assembly when required.

While primarily serving residential customers, Maine Woodworks also runs a Trade+Hospitality program for commercial and design-trade clients. The company sells directly through its Shopify-powered website and offers a gallery of configurable styles.

The brand positions itself on elevated design and heirloom-quality construction, highlighting that every piece is built one at a time in Maine to last for generations. Sustainable sourcing and full customization are cited as core differentiators.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture manufacturing", "Handcrafted woodworking", "English dovetail joinery", "Custom finishing (eco-friendly)", "Made-to-order production", "White glove delivery", "Assembly service", "Design customization (panels, legs, knobs)"], "industries": ["Residential furniture", "Hospitality", "Interior design trade"], "materials": ["Sustainable hardwood (regionally sourced)"], "equipment": [], "volume": "", "lead_time": "6-8 weeks", "tolerances": "", "built_on": ["Handcrafted in Maine, one piece at a time", "Full customization of panels, legs, knobs, and finishes", "Regionally sourced sustainable hardwood with English dovetail joinery", "White-glove delivery with included assembly", "Six-to-eight-week production lead times"], "facts_used": ["Founded 1991 -> db", "Headquarters Saco, Maine -> db", "Builds custom-made furniture in Maine -> db, page ''/''", "Handcrafted from sustainable hardwood -> page ''/''", "English dovetail joinery -> page ''/''", "Made to order with customization -> page ''/''", "Categories: bedroom, dining, entryway, farmhouse, occasional, office -> page ''/''", "Production lead times six to eight weeks -> db (products array)", "White glove delivery with assembly -> db (capabilities), page ''/''", "Trade+Hospitality program -> page ''/''", "Powered by Shopify -> page ''/''"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We build custom-made furniture in Maine", "founded_year": "1991", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='maine-woodworks' AND approved AND profile IS NULL;
UPDATE companies SET description='Majors Plastics Inc. was founded in 1953 by Ben Pfeiffer and Eli Dahir in Omaha, Nebraska. The company began as an injection molding operation and moved to its current Plant One location in 1968. In 2013, after a gradual transition, it became a 100 percent employee-owned ESOP, a structure that now governs its corporate culture and long-term planning.

Today the company runs four molding facilities—three in Omaha totaling over 300,000 square feet with more than 120 molding machines, and one in Reynosa, Mexico, with 128,000 square feet and 36 machines. Its core capabilities include precision injection molding, true two-shot molding, overmolding, insert molding, and ISO Class-7 cleanroom molding with laminar HEPA-controlled airflow. Secondary services cover ultrasonic welding, heat staking, pad printing, painting, manual assembly, and custom packaging, supported by in-house engineering and tool-room resources. Approximately 500 employees handle high- and medium-volume production runs.

Its customer base includes 3M, which has recognized the company multiple times as a Supplier of the Year, and BD, which named it a Supply Chain Excellence Supplier of the Year. Earlier diversification brought energy-related products, thermoset tableware, and rigid computer-disc preparatory work, but the current focus remains on tightly toleranced components for regulated industries.

The company attributes its differentiation to its employee-ownership model, a disciplined ISO 9001:2015 quality system that targets Cpk values above 1.33 and AQL levels as low as 0.040, and a commitment to personalized support from initial design concept through finished product. Statistical process control, PPAP, IQ/OQ/PQ validations, and real-time particle-contamination testing are standard practice.', certifications=ARRAY['ISO 9001:2015','ISO 14644-1 Class 7']::text[], profile='{"capabilities": ["Injection Molding", "Overmolding", "Insert Molding", "Two-Shot Molding", "ISO Class-7 Cleanroom Molding", "Assembly", "Ultrasonic Welding", "Heat Staking", "Manual Assembly", "Pad Printing", "Heat Stamping", "Painting", "Custom Packaging", "Engineering Support", "Tool Room Support", "Mold Repair and Maintenance", "Particle Contamination Testing", "Robotics & Automation", "Laminar HEPA-Controlled Airflow", "Real-time ASTM E2090 Testing", "Warehousing", "Distribution"], "industries": ["Pharmaceutical", "Medical Devices", "Health & Safety", "Energy", "Consumer Electronics", "Tableware", "Industrial Manufacturing"], "materials": [], "equipment": ["Ziess Coordinate Measuring Machines", "OGP Smartscopes (Flash 500''s and desktop)", "Optical Comparators", "Spectrophotometers (Perkin Elmer and Hunter handheld)", "Zeiss Digital Microscope System", "Hazegard Transparency Testers", "Gauge Blocks", "Micrometers", "Height Gauges", "Calipers", "Granite Plates and Angle Blocks", "Melt Flow Indicators", "Moisture Analyzers"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% employee-owned ESOP structure", "ISO Class-7 cleanroom molding with laminar HEPA-controlled airflow from molding to packaging", "Statistical process control targeting Cpk > 1.33 and AQL as low as 0.040", "Over 300,000 sq ft of U.S. manufacturing space with 120+ molding machines", "Full engineering and tool-room support from development through product lifetime"], "facts_used": ["Founded 1953 by Ben